    if not self._meta_limits and meta_limits:
        self._meta_limits = [
            MetaLimit(
                limit_provider=meta_limits,
                key_function=self._key_func,
            ).bind(self)
            if not isinstance(meta_limits, MetaLimit)
            else meta_limits.bind(self)
        ]

